<script setup lang="ts">
import {useHysRootAttrs} from '../../config'
const hysRootAttrs=useHysRootAttrs()

import {ChevronLeft,ChevronRight} from 'lucide-vue-next';
import {computed,ref,watch} from 'vue';export interface CalendarEvent{id:string;date:string;title:string}const props=defineProps<{modelValue?:string;events?:CalendarEvent[];disabled?:boolean;readonly?:boolean;disabledDate?:(date:string)=>boolean}>();const emit=defineEmits<{'update:modelValue':[date:string];select:[date:string];event:[id:string]}>();const now=new Date();const year=ref(now.getFullYear()),month=ref(now.getMonth());watch(()=>props.modelValue,value=>{if(!value||!/^\d{4}-\d{2}-\d{2}$/.test(value))return;const selected=new Date(value+'T00:00:00Z');if(!Number.isNaN(selected.getTime())&&selected.toISOString().slice(0,10)===value){year.value=selected.getUTCFullYear();month.value=selected.getUTCMonth()}},{immediate:true});const label=computed(()=>`${year.value}年${month.value+1}月`);const days=computed(()=>{const first=(new Date(year.value,month.value,1).getDay()+6)%7;const count=new Date(year.value,month.value+1,0).getDate();return [...Array(first).fill(null),...Array.from({length:count},(_,i)=>i+1)]});function shift(n:number){const d=new Date(year.value,month.value+n,1);year.value=d.getFullYear();month.value=d.getMonth()}function date(d:number){return `${year.value}-${String(month.value+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`}
</script>
<template><section v-bind="hysRootAttrs" class="hys-ui-ent-panel"><header class="hys-ui-ent-toolbar"><button type="button" aria-label="上个月" @click="shift(-1)"><ChevronLeft :size="16" aria-hidden="true"/></button><strong>{{label}}</strong><button type="button" aria-label="下个月" @click="shift(1)"><ChevronRight :size="16" aria-hidden="true"/></button></header><div class="hys-ui-ent-calendar"><strong v-for="w in ['一','二','三','四','五','六','日']" :key="w">{{w}}</strong><div v-for="(d,i) in days" :key="i" class="hys-ui-ent-calendar-day"><button type="button" v-if="d" :disabled="disabled||disabledDate?.(date(d))" :aria-readonly="readonly||undefined" :aria-pressed="modelValue===date(d)" @click="!readonly&&(emit('select',date(d)),emit('update:modelValue',date(d)))"><slot name="date" :date="date(d)" :day="d">{{d}}</slot></button><button type="button" v-for="ev in (events||[]).filter(x=>d&&x.date===date(d))" :key="ev.id" class="hys-ui-ent-event" :disabled="disabled" @click="emit('event',ev.id)">{{ev.title}}</button></div></div></section></template>
